/* A save loaded later (cloud login, save code) may hold an old made-up ticker: add it back, delisted, so it can be sold. */
(() => {
  const n0 = normalizeAcct;
  normalizeAcct = function (a) {
    const r = n0.apply(this, arguments);
    try {
      if (ASSETS.length) {
        const raw = JSON.stringify(r || a),
          L = legacyList();
        let added = 0;
        for (const m of raw.matchAll(/"([A-Z]{3,5})"/g)) {
          const sym = m[1];
          if (SIM[sym] || !L.has(sym)) continue;
          const x = makeLite([...L.get(sym).slice(0, 6), 'legacy']);
          SIM[sym] = x;
          ASSETS.push(x);
          LITE.push(x);
          liteBackfill(x, simT || nowSec());
          added++;
        }
        if (added) needRender = true;
      }
    } catch (e) {
      console.error(e);
    }
    return r;
  };
})();
